<?php

declare(strict_types=1);

namespace Saij\ThemeDevTest\Post;

use Saij\WpAppFramework\Query\Field\EnumField;
use Saij\WpAppFramework\Query\Field\IdField;
use Saij\WpAppFramework\Query\Field\IntField;
use Saij\WpAppFramework\Query\Field\PostField;
use Saij\WpAppFramework\Query\Field\StringField;
use Saij\WpAppFramework\Query\MetaFields;

/**
 * The fields of EventDetails for queries; generated by `wp-app-framework meta-fields`, change it as you like.
 */
#[MetaFields(EventDetails::class)]
final class EventDetailsFields
{
    public static function start(): StringField
    {
        return new StringField(EventDetails::class, 'start');
    }

    public static function end(): StringField
    {
        return new StringField(EventDetails::class, 'end');
    }

    public static function capacity(): IntField
    {
        return new IntField(EventDetails::class, 'capacity');
    }

    /**
     * @return EnumField<EventKind>
     */
    public static function kind(): EnumField
    {
        return new EnumField(EventDetails::class, 'kind', EventKind::class);
    }

    /**
     * @return PostField<Venue>
     */
    public static function venue(): PostField
    {
        return new PostField(EventDetails::class, 'venue', Venue::class);
    }

    public static function note(): StringField
    {
        return new StringField(EventDetails::class, 'note');
    }

    public static function photo(): IdField
    {
        return new IdField(EventDetails::class, 'photo');
    }

    public static function website(): StringField
    {
        return new StringField(EventDetails::class, 'website');
    }
}
